head.script:
scwin.__checkErrLog = function() {
    var log = WebSquare.logger.getLog();
    return log.indexOf("Cannot read property 'style' of null");
}
scwin.unitTest = function() {
    //Unit test
    WebSquare.wUnit.start();
    //Verify 1. 로그보기화면에 오류가 발생하지 않고 정상적으로 동작한다.
    //1. The log view screen does not fail and works normally.
    WebSquare.wUnit.addCommand("assert", "scwin.__checkErrLog() == -1", "true");
    WebSquare.wUnit.addCommand("pause", "500");
    //Run and Stop test
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    TAB_CTL.setHeight("200");
    //         TAB_CTL.setSize({"height":"200"}); 
    //Function unitTest
    //Create buy Truong.Luu
    //Create date 26-Feb-2018
    //End unitTest
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
